<?php require_once __DIR__.'/includes/functions.php';$pageTitle='AR Experience';$posters=db()->query("SELECT * FROM ar_posters WHERE status='active' ORDER BY name")->fetchAll();require __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/mind-ar@1.2.2/dist/mindar-image.prod.css">
<div class="ar-shell"><div class="container py-5 text-center"><i class="fa-solid fa-vr-cardboard fa-3x text-warning mb-3"></i><h1>Welcome to AR Tourism</h1><p class="lead">Choose a compiled poster, allow camera access and explore.</p><?php if (!isset($_SERVER['HTTPS'])&&!in_array($_SERVER['HTTP_HOST']??'', ['localhost','127.0.0.1'])):?><div class="alert alert-warning">Camera access requires HTTPS.</div><?php endif;?><select id="poster" class="form-select mx-auto mb-3" style="max-width:360px"><option value="">Choose a poster</option><?php foreach ($posters as $p):?><option value="<?=url('api/ar/poster.php?id='.$p['id'])?>" data-ready="<?=e($p['target_status'])?>"><?=e($p['name'])?> — <?=e($p['target_status'])?></option><?php endforeach;?></select><button id="startAr" class="btn btn-warning btn-lg" disabled><i class="fa-solid fa-camera"></i> START AR</button><div id="arMessage" class="mt-4 text-secondary">The administrator must compile a poster before tracking can begin.</div><div id="arViewport" class="mt-4 d-none position-relative" style="height:55vh"><div id="arContent" class="ar-card d-none text-start"><strong id="arName"></strong><p id="arDescription" class="mb-2"></p><a id="arMap" class="btn btn-sm btn-success" target="_blank" rel="noopener"><i class="fa-solid fa-map"></i> Map</a></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/mind-ar@1.2.2/dist/mindar-image.prod.js"></script><script src="https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js"></script>
<script>const p=document.querySelector('#poster'),b=document.querySelector('#startAr'),msg=document.querySelector('#arMessage');p.onchange=()=>{const o=p.selectedOptions[0];b.disabled=!p.value||o.dataset.ready!=='READY';msg.textContent=o.dataset.ready==='READY'?'Ready to start.':'This poster has not been compiled yet.'};b.onclick=async()=>{try{const r=await fetch(p.value),data=await r.json();if(!data.poster.target_url){msg.textContent='Target file is missing. Ask an administrator to compile this poster.';return}await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});msg.textContent='Camera permission granted. MindAR target is ready to connect.';document.querySelector('#arViewport').classList.remove('d-none');if(data.hotspots[0]){const h=data.hotspots[0];document.querySelector('#arName').textContent=h.attraction_name||h.label;document.querySelector('#arDescription').textContent=h.short_description||'Explore this attraction.';document.querySelector('#arMap').href=h.maps_url||'#';document.querySelector('#arContent').classList.remove('d-none')}}catch(e){msg.textContent='Camera access was denied or the target could not be loaded.'}};</script><?php require __DIR__.'/includes/footer.php';?>
